#!/usr/bin/env python3
"""Record actual image viewing and independently verify each prepared file."""
import fcntl,importlib.util,io
from pathlib import Path
from PIL import Image
s=importlib.util.spec_from_file_location('b',Path(__file__).with_name('continuous-warsaw-batch-000094.py'));b=importlib.util.module_from_spec(s);s.loader.exec_module(b);h=b.h;i=b.i
lock=(b.R/'worker.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
observations={'498703': 'Complete supplied wooden panel with winged John the Baptist turned left, a chalice containing the infant Christ, and scroll. Wide gold border and all four board edges visible. Matches IK 81 description. A nineteenth-century repetition of a seventeenth-century model, not the model itself; source creation bounds 1801–1850 retained.', '498372': 'Full surviving framed panel: frontal Christ blessing and holding an open Gospel, blue cloak, with extensive paint losses showing wood in the background. All outside frame edges visible; native IK 149 composition matches source. Qualified Uniate workshop (?) and Belarusian workshop labels remain qualified. Late eighteenth-century text preserved with conservative whole-century 1701–1800 bounds, not an invented narrow date.', '498340': 'Full rectangular November calendar icon with five horizontal rows of saints/scenes, dark perimeter and grey photographic surround. All board edges visible. Matches IK 119 and source five-register description. Counts as one physical panel; not thirty separate works. Small inscriptions not individually read.', '498379': 'Whole wooden icon: winged Michael centrally holding a cloth bearing Christ’s face, flanked by four saints. Broad brown board border and all edges visible. Matches IK 16 source description; no claim to have read all saint labels.', '455230': 'Complete framed icon: three winged angels seated around a table, central angel frontal, architecture left and tree/rock above, gilt patterned background. Full surviving composition and external frame visible. Matches IK 148 from the unknown workshop active in Torki. Seventeenth-century date preserved.', '498686': 'Complete small panel with the frontal bust of Christ, long divided hair, gold cross halo, dark red-green garments, red and green border. All physical edges visible. Native IK 71 source primary image and description agree. Second half nineteenth-century date retained.', '498396': 'Full wooden panel: Virgin centrally with raised right hand, surrounded by kneeling petitioners and angels, Christ emerging above. Entire board perimeter visible with source wear. Matches IK 173. Source reverse workshop notes were not viewed. Turn of eighteenth/nineteenth-century text preserved with broad 1701–1900 bounds.'}
files=[];decisions=[]
for r in i.selected(b.B)['rows']:
 im=h.load(i.folder(b.B)/'prepared'/(r['artwork_id']+'.json'));assert im['state']=='prepared';raw=Path(im['path']).read_bytes();orig=Path(im['original_path']).read_bytes();assert h.sha(raw)==im['sha256'] and h.sha(orig)==im['source_sha256'] and len(raw)==im['bytes']<=100000
 with Image.open(io.BytesIO(raw)) as pic:pic.load();assert pic.format=='JPEG' and pic.size==(im['width'],im['height'])
 with Image.open(io.BytesIO(orig)) as pic:pic.load();assert abs(pic.width/pic.height-im['width']/im['height'])<.03
 assert '/Documents/' not in im['original_path']
 decisions.append(dict(artwork_id=r['artwork_id'],source_id=r['native_id'],artist=r['creator_label'],sha256=im['sha256'],decision='accept',viewed_individually=True,viewed_path=im['path'],tool='functions tools.view_image',observations=observations[r['native_id']],flag_resolution='Individual actual derivative viewed. The manual_visual_required switch conservatively flags the 315-pixel museum derivative, but the actual image is a complete authentic icon, not a placeholder. Full supplied frame, native inventory and source description match; no unseen reverse or tiny-inscription claim.',identity_confidence=.99,confidence_basis='Exact native object/image, inventory, dimensions, source description and observed physical composition; editorial judgment, not calibrated probability.'))
 files.append(dict(artwork_id=r['artwork_id'],sha256=im['sha256'],bytes=im['bytes'],complete_decode=True,proportions_preserved=True,original_sha256=im['source_sha256'],original_path=im['original_path']))
assert len(decisions)==7
review=dict(at=h.now(),batch_quality_decision='accept',reviewer='Codex actual image viewing',decisions=decisions,all_selected_files_individually_viewed=True,sample_only_files=[],limitations='Museum source images are 315 px wide. Compositions and complete supplied frames reviewed; no claim to inspect absent reverse views or tiny illegible inscriptions. Originals decoded and hashed; derivatives individually visually viewed.')
h.save(i.folder(b.B)/'visual-review.json',review);b.save('actual-visual-review.json',review);b.save('prewrite-file-verification.json',dict(at=h.now(),files=files,plan_sha256=h.pinned(b.PHASE)[1]))
print('7 actual per-image visual decisions and complete file checks saved')
